examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
    HStack(spacing: MonarchTokens.Space.space6) {
        Text({{rows.0.label}}).monarchTextStyle(.label)
        Spacer(minLength: 0)
        Text(monarchTabular: {{rows.0.value|double}}, format: .number.locale(Locale(identifier: {{locale}})))
            .monarchTextStyle(.body)
    }
    HStack(spacing: MonarchTokens.Space.space6) {
        Text({{rows.1.label}}).monarchTextStyle(.label)
        Spacer(minLength: 0)
        Text(monarchTabular: {{rows.1.value|double}}, format: .number.locale(Locale(identifier: {{locale}})))
            .monarchTextStyle(.body)
    }
    HStack(spacing: MonarchTokens.Space.space6) {
        Text({{rows.2.label}}).monarchTextStyle(.label)
        Spacer(minLength: 0)
        Text(monarchTabular: {{rows.2.value|double}}, format: .number.locale(Locale(identifier: {{locale}})))
            .monarchTextStyle(.body)
    }
}

